function() {
  var dataLayerContent = window.dataLayer || [];
  var pageName = undefined;

  for (var i = dataLayerContent.length - 1; i >= 0; i--) {
    if (dataLayerContent[i] &&
        dataLayerContent[i].page_name !== undefined &&
        dataLayerContent[i].page_name !== null &&
        dataLayerContent[i].page_name !== '') {
      pageName = dataLayerContent[i].page_name;
      break;
    }
  }

  if (pageName === undefined) {
    for (var j = dataLayerContent.length - 1; j >= 0; j--) {
      if (dataLayerContent[j] &&
          dataLayerContent[j].pageInfo &&
          dataLayerContent[j].pageInfo.pageName !== undefined &&
          dataLayerContent[j].pageInfo.pageName !== null &&
          dataLayerContent[j].pageInfo.pageName !== '') {
        pageName = dataLayerContent[j].pageInfo.pageName;
        break;
      }
    }
  }

  return pageName;
}
